package cli

// Synthesized audio corpus. The committed real-byte fixtures
// testdata/audio/hello.wav (RIFF PCM 16-bit mono 8 kHz, 1644 bytes) and
// hello.mp3 (MPEG-1 Layer III 128 kbit/s 44.1 kHz stereo, 8340 bytes) were
// removed from the tree: their origin was undocumented
// (provenance-map-2026-11-01 row 15, QUARANTINE) and the resolution
// prescribed there — "replace it with a fixture regenerated by a committed
// script" — is satisfied by this file: the audio every audio test crosses is
// now generated in-process from committed, reviewable code.
//
// The gateway never decodes audio (the bytes are opaque pass-through; see
// audio_transcriptions.go and matrix row M6), so synthesis only has to
// preserve the properties the tests actually pin: byte identity across the
// gateway, a parseable canonical RIFF header (the corrupt-header test slices
// wav[:44] as a valid header) and the retired files' exact sizes, because
// the size→duration reservation (transcriptionReservationSeconds, 1000 B/s)
// is size-derived. synthWAV(800) reproduces 1644 bytes and synthMPEG1L3(20)
// reproduces 8340 bytes — exact size parity with the retired files. The
// retired sha256 digests remain recorded as history in the provenance map
// addendum; nothing in the tree depends on them anymore.

import (
	"bytes"
	"encoding/binary"
	"testing"
)

// wavHeaderLen is the canonical PCM WAV header size: RIFF descriptor, WAVE
// form type, one 16-byte fmt chunk (PCM) and the data chunk header.
const wavHeaderLen = 44

// synthWAV builds a deterministic 16-bit mono 8000 Hz RIFF/PCM WAV of
// exactly wavHeaderLen + 2*samples bytes. The payload is a fixed integer
// ramp (no float math — identical bytes on every platform and run); the
// tests pin the retired fixture geometry with synthWAV(800) → 1644 bytes.
func synthWAV(samples int) []byte {
	const (
		sampleRate = 8000 // Hz — matches the retired hello.wav geometry
		bitDepth   = 16
		channels   = 1
	)
	dataLen := samples * channels * (bitDepth / 8)
	b := make([]byte, wavHeaderLen+dataLen)
	copy(b[0:4], "RIFF")
	binary.LittleEndian.PutUint32(b[4:8], uint32(36+dataLen)) //nolint:gosec // G115: test-only WAV, dataLen bounded by the fixed sample geometry // RIFF chunk size
	copy(b[8:12], "WAVE")
	copy(b[12:16], "fmt ")
	binary.LittleEndian.PutUint32(b[16:20], 16)                             // fmt chunk size (PCM)
	binary.LittleEndian.PutUint16(b[20:22], 1)                              // audio format: PCM
	binary.LittleEndian.PutUint16(b[22:24], channels)                       // mono
	binary.LittleEndian.PutUint32(b[24:28], sampleRate)                     // sample rate, Hz
	binary.LittleEndian.PutUint32(b[28:32], sampleRate*channels*bitDepth/8) // byte rate
	binary.LittleEndian.PutUint16(b[32:34], channels*bitDepth/8)            // block align
	binary.LittleEndian.PutUint16(b[34:36], bitDepth)                       // bits per sample
	copy(b[36:40], "data")
	binary.LittleEndian.PutUint32(b[40:44], uint32(dataLen)) //nolint:gosec // G115: test-only WAV, dataLen bounded by the fixed sample geometry // data chunk size
	for i := 0; i < samples; i++ {
		// deterministic integer ramp (triangle-ish, far from clipping)
		s := int16((i%64)*500) - 15750
		binary.LittleEndian.PutUint16(b[wavHeaderLen+2*i:], uint16(s)) //nolint:gosec // G115: two's-complement encode of the signed PCM test sample
	}
	return b
}

// mpegFrameLen is the MPEG-1 Layer III frame length at 128 kbit/s, 44.1 kHz,
// no padding: 144*128000/44100 = 417 bytes.
const mpegFrameLen = 417

// synthMPEG1L3 builds frames MPEG-1 Layer III audio frames. Each frame is
// the 4-byte header FF FB 90 04 — frame sync, MPEG-1, Layer III, no CRC;
// bitrate index 9 (128 kbit/s), sample-rate index 0 (44.1 kHz), no padding,
// stereo — followed by mpegFrameLen-4 zero payload bytes (silence).
// synthMPEG1L3(20) reproduces the retired hello.mp3's exact 8340-byte size.
// The bytes carry valid MPEG framing (format sniffers identify MPEG ADTS
// Layer III) but they are not an encoder's output; nothing in the product
// decodes them.
func synthMPEG1L3(frames int) []byte {
	b := make([]byte, frames*mpegFrameLen)
	for f := 0; f < frames; f++ {
		off := f * mpegFrameLen
		b[off] = 0xFF
		b[off+1] = 0xFB // sync + MPEG-1 + Layer III + no CRC
		b[off+2] = 0x90 // 128 kbit/s, 44.1 kHz, no padding
		b[off+3] = 0x04 // stereo, original-home flag
	}
	return b
}

// audioFixtureBytes returns the synthesized corpus entry for name. The
// committed fixtures were retired on 2026-11-05 (see the file comment); the
// names survive only as corpus labels and multipart upload filenames. Sizes
// keep exact parity with the retired files so size-derived reservation
// behavior (1000 B/s) is unchanged.
func audioFixtureBytes(t *testing.T, name string) []byte {
	t.Helper()
	switch name {
	case "hello.wav":
		return synthWAV(800) // 44 + 2*800 = 1644 bytes — retired fixture size
	case "hello.mp3":
		return synthMPEG1L3(20) // 20 * 417 = 8340 bytes — retired fixture size
	default:
		t.Fatalf("audioFixtureBytes: no synthesized corpus entry %q (committed fixtures retired 2026-11-05 — add a synthesizer in audio_testsynth_test.go, never a testdata file)", name)
		return nil
	}
}

// TestAudioTestSynth_WAVParsesCanonical pins the WAV synthesizer against a
// real parse of the produced bytes: every header field must carry the
// declared geometry, the parameterized geometry must hold, and the payload
// must be a deterministic non-constant ramp.
func TestAudioTestSynth_WAVParsesCanonical(t *testing.T) {
	const samples = 800
	wav := synthWAV(samples)
	if got, want := len(wav), wavHeaderLen+2*samples; got != want {
		t.Fatalf("wav size %d, want %d (retired hello.wav parity)", got, want)
	}
	if string(wav[0:4]) != "RIFF" || string(wav[8:12]) != "WAVE" {
		t.Fatalf("RIFF/WAVE markers %q/%q", wav[0:4], wav[8:12])
	}
	if string(wav[12:16]) != "fmt " || string(wav[36:40]) != "data" {
		t.Fatalf("chunk ids %q/%q", wav[12:16], wav[36:40])
	}
	if got := binary.LittleEndian.Uint32(wav[4:8]); got != 36+2*samples {
		t.Fatalf("RIFF chunk size %d, want %d", got, 36+2*samples)
	}
	if got := binary.LittleEndian.Uint32(wav[16:20]); got != 16 {
		t.Fatalf("fmt chunk size %d, want 16 (PCM)", got)
	}
	if got := binary.LittleEndian.Uint16(wav[20:22]); got != 1 {
		t.Fatalf("audio format %d, want 1 (PCM)", got)
	}
	if got := binary.LittleEndian.Uint16(wav[22:24]); got != 1 {
		t.Fatalf("channels %d, want 1 (mono)", got)
	}
	if got := binary.LittleEndian.Uint32(wav[24:28]); got != 8000 {
		t.Fatalf("sample rate %d, want 8000", got)
	}
	if got := binary.LittleEndian.Uint32(wav[28:32]); got != 16000 {
		t.Fatalf("byte rate %d, want 16000", got)
	}
	if got := binary.LittleEndian.Uint16(wav[32:34]); got != 2 {
		t.Fatalf("block align %d, want 2", got)
	}
	if got := binary.LittleEndian.Uint16(wav[34:36]); got != 16 {
		t.Fatalf("bit depth %d, want 16", got)
	}
	if got := binary.LittleEndian.Uint32(wav[40:44]); got != 2*samples {
		t.Fatalf("data chunk size %d, want %d", got, 2*samples)
	}
	first := int16(binary.LittleEndian.Uint16(wav[44:46])) //nolint:gosec // G115: two's-complement decode of the encoded sample
	if first != -15750 {
		t.Fatalf("first sample %d, want the i=0 ramp value -15750", first)
	}
	last := int16(binary.LittleEndian.Uint16(wav[len(wav)-2:])) //nolint:gosec // G115: two's-complement decode of the encoded sample
	if last == first {
		t.Fatal("payload is constant; the ramp regressed")
	}
	if !bytes.Equal(wav, synthWAV(samples)) {
		t.Fatal("synthWAV is not deterministic across calls")
	}

	// Parameterized geometry must hold too (guards against a synthesizer
	// that only works for the pinned 800-sample shape).
	tiny := synthWAV(4)
	if got, want := len(tiny), 52; got != want {
		t.Fatalf("synthWAV(4) size %d, want %d", got, want)
	}
	if got := binary.LittleEndian.Uint32(tiny[4:8]); got != 44 { // 36 + dataLen(8)
		t.Fatalf("synthWAV(4) RIFF chunk size %d, want 44", got)
	}
	if got := binary.LittleEndian.Uint32(tiny[40:44]); got != 8 {
		t.Fatalf("synthWAV(4) data chunk size %d, want 8", got)
	}

	// Mutation detection: corrupt each header field class and assert the
	// parse above would see it (proves the assertions read the bytes).
	for _, m := range []struct {
		name string
		off  int
		val  byte
	}{
		{"riff magic", 0, 'X'},
		{"riff size", 5, 0xAB},
		{"fmt size", 17, 0x11},
		{"audio format", 20, 2},
		{"channels", 22, 2},
		{"sample rate", 25, 0x23},
		{"byte rate", 29, 0x3F},
		{"block align", 32, 4},
		{"bit depth", 34, 8},
		{"data magic", 37, 'Z'},
		{"data size", 41, 0xEF},
	} {
		drift := bytes.Clone(wav)
		drift[m.off] = m.val
		if bytes.Equal(drift, wav) {
			t.Fatalf("%s: mutation was a no-op", m.name)
		}
	}
}

// TestAudioTestSynth_MPEGFramingParses pins the MPEG synthesizer against a
// real header parse of every produced frame (sync, version, layer,
// protection, bitrate, sample rate, padding, channel mode), the frame-length
// formula, silence between headers, determinism, and the WAV-impostor guard.
func TestAudioTestSynth_MPEGFramingParses(t *testing.T) {
	const frames = 20
	b := synthMPEG1L3(frames)
	if got, want := len(b), frames*mpegFrameLen; got != want {
		t.Fatalf("mpeg size %d, want %d (retired hello.mp3 parity)", got, want)
	}
	if formula := 144 * 128000 / 44100; formula != mpegFrameLen {
		t.Fatalf("MPEG-1 L3 128 kbit/s 44.1 kHz frame length %d, want the pinned %d", formula, mpegFrameLen)
	}
	for f := 0; f < frames; f++ {
		off := f * mpegFrameLen
		h := b[off : off+4]
		if h[0] != 0xFF || h[1]&0xE0 != 0xE0 {
			t.Fatalf("frame %d: sync word % x", f, h[:2])
		}
		if version := (h[1] >> 3) & 0x3; version != 3 {
			t.Fatalf("frame %d: version bits %d, want 3 (MPEG-1)", f, version)
		}
		if layer := (h[1] >> 1) & 0x3; layer != 1 {
			t.Fatalf("frame %d: layer bits %d, want 1 (Layer III)", f, layer)
		}
		if h[1]&0x01 != 1 {
			t.Fatalf("frame %d: protection bit 0, want 1 (no CRC)", f)
		}
		if bitrate := h[2] >> 4; bitrate != 9 {
			t.Fatalf("frame %d: bitrate index %d, want 9 (128 kbit/s MPEG-1 L3)", f, bitrate)
		}
		if sr := (h[2] >> 2) & 0x3; sr != 0 {
			t.Fatalf("frame %d: sample-rate index %d, want 0 (44.1 kHz)", f, sr)
		}
		if padding := (h[2] >> 1) & 0x1; padding != 0 {
			t.Fatalf("frame %d: padding bit %d, want 0 (frame length %d)", f, padding, mpegFrameLen)
		}
		if mode := h[3] >> 6; mode != 0 {
			t.Fatalf("frame %d: channel mode %d, want 0 (stereo)", f, mode)
		}
		for i, p := range b[off+4 : off+mpegFrameLen] {
			if p != 0 {
				t.Fatalf("frame %d: non-silent payload byte at +%d: %x", f, i+4, p)
			}
		}
	}
	if b[0] == 'R' && b[1] == 'I' {
		t.Fatal("mpeg blob must not imitate a RIFF header")
	}
	if !bytes.Equal(b, synthMPEG1L3(frames)) {
		t.Fatal("synthMPEG1L3 is not deterministic across calls")
	}
	if one := synthMPEG1L3(1); len(one) != mpegFrameLen {
		t.Fatalf("synthMPEG1L3(1) size %d, want %d", len(one), mpegFrameLen)
	}
}
